uint xe_vf_needed_words(uint format, uint used)
{
    switch (format)
    {
        case 6u:
        case 7u:
        {
            return 1u;
        }
        case 16u:
        case 17u:
        {
            return uint((used & 7u) != 0u);
        }
        case 25u:
        case 31u:
        {
            return uint((used & 3u) != 0u);
        }
        case 26u:
        case 32u:
        {
            return uint((used & 3u) != 0u) | (((used & 12u) != 0u) ? 2u : 0u);
        }
        case 33u:
        case 36u:
        {
            return used & 1u;
        }
        case 34u:
        case 37u:
        {
            return used & 3u;
        }
        case 57u:
        {
            return used & 7u;
        }
    }
    return used;
}

